// "Do not send patches generated by an LLM." and "Code must not be
// generated by AI.": sending or opening AI-made work, and work that must
// not be made by AI, refused in a sentence about contributions, are bans
// of AI help that block agent runs. Encouragement ("Don't hesitate to open
// a pull request", "You don't need to open an issue first") refuses
// nothing, and "until you have disclosed" is a condition the contributor
// meets. The sentences are written for these tests.
import assert from "node:assert/strict";
import test from "node:test";
import { respectChecks } from "./contribution.js";
import { classifyPolicy } from "./project-policy.js";

function read(text: string) {
  const document = `# Contributing\n\n${text}\n`;
  const findings = classifyPolicy("CONTRIBUTING.md", document);
  const rules = { checkedAt: "2026-10-20T10:00:00.000Z", findings, filesRead: ["CONTRIBUTING.md"] };
  return {
    bans: findings.filter((finding) => finding.kind === "ban").map((finding) => finding.contribution),
    agent: respectChecks({ body: "Prepared with Codex, which wrote the patch.", rules }, "en").map((check) => check.id),
  };
}

test("sending or opening AI-made work, or work that must not be made by AI, is a ban", () => {
  for (const text of [
    "Do not send patches generated by an LLM.",
    "Please don't send us PRs written by Copilot.",
    "Do not open pull requests with AI-generated code.",
    "Code must not be generated by AI.",
    "Contributions must not be generated by AI tools.",
    "Patches can't be written by an LLM.",
    "Code must never be generated by AI.",
    "Code must not be AI-generated.",
    "Contributions must not be AI-assisted.",
    "Code must not be LLM-generated.",
    "Patches must not be Copilot-generated.",
    // A refusal that says how the maintainers feel, or that they need no such work.
    "We don't feel comfortable accepting AI-generated contributions.",
    "We don’t feel comfortable accepting AI-generated contributions.",
    "We do not currently feel comfortable reviewing pull requests generated by LLMs.",
    "At this time we don't feel comfortable accepting contributions that include AI-generated code.",
    "We do not feel comfortable including LLM-generated code in this project.",
    "We don't feel comfortable accepting AI-generated pull requests.",
    "The maintainers don't feel comfortable reviewing code written by ChatGPT.",
    "This project does not need contributions generated by AI.",
    "We do not need contributions written by ChatGPT.",
    "We do not need or accept AI-generated code.",
  ]) {
    const result = read(text);
    assert.deepEqual(result.bans, [true], text);
    assert.ok(result.agent.includes("ai-ban"), text);
  }
});

test("encouragement, work made without AI, or the name OpenAI is no ban", () => {
  for (const text of [
    "Don't hesitate to open a pull request, even if you used AI tools to help.",
    "Don't hesitate to submit a pull request, even if you used AI tools to help.",
    "Don't be afraid to contribute, even with AI-assisted code.",
    "Please don't be shy about sending a patch, AI-assisted or not.",
    "Tests should not be written by hand; generate them with the fixtures script.",
    "Contributors do not need OpenAI accounts; AI tools are optional.",
    "You don't need to open an issue before sending a pull request, even for AI-assisted changes.",
    "You don't need to send a patch to the mailing list; AI-assisted PRs on GitHub are fine.",
    "Don't wait to open a pull request, even if you used AI tools.",
    "Do not forget to open a PR that discloses AI tool usage.",
    "You do not have to open an issue for small fixes, even AI-assisted ones.",
    "You don't need to open an issue first, even for AI-assisted changes.",
    "Don't forget to open a pull request and mention any AI tools you used.",
    "Don't worry about sending a perfect patch, even if you used AI tools.",
    "Please don't feel bad about opening a PR that was written with Copilot.",
    "Don't be scared to open a pull request, even with AI-assisted code.",
    "Do not wait to open a pull request with AI-assisted code.",
    "Don't feel obliged to send a patch, even with AI tools.",
    "Please don't feel guilty about sending a patch written with Copilot.",
    "Don't feel pressured to open a pull request, even with AI-assisted code.",
  ]) {
    const result = read(text);
    assert.deepEqual(result.bans, [], text);
    assert.ok(!result.agent.includes("ai-ban"), text);
  }
});

test("opening a pull request only after disclosing or reviewing the AI help is a condition, not a ban", () => {
  for (const text of [
    "Do not open a pull request until you have disclosed any AI tools you used.",
    "Do not open a pull request before disclosing any AI tools you used.",
    "Do not open a PR with AI-generated code before you have reviewed it.",
  ]) {
    const result = read(text);
    assert.deepEqual(result.bans, [false], text);
    assert.ok(!result.agent.includes("ai-ban"), text);
  }
});
